import{_ as o,o as t,c as a,a0 as n}from"./chunks/framework.BSa2j5Vp.js";const c=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),r={name:"guide/troubleshooting.md"};function i(s,e,d,l,u,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="no-muse-models-listed" tabindex="-1">No Muse models listed <a class="header-anchor" href="#no-muse-models-listed" aria-label="Permalink to &quot;No Muse models listed&quot;">​</a></h2><p>Run <code>muse login</code>, restart OpenCode, and refresh providers. If the provider shows the <em>&quot;Muse setup required&quot;</em> placeholder, the CLI reported no usable catalog — that is the plugin telling you the truth instead of offering a model that would fail on use.</p><h2 id="duplicate-plugin-id-opencode-muse" tabindex="-1">&quot;Duplicate plugin ID: opencode-muse&quot; <a class="header-anchor" href="#duplicate-plugin-id-opencode-muse" aria-label="Permalink to &quot;&quot;Duplicate plugin ID: opencode-muse&quot;&quot;">​</a></h2><p>The package entry and the local shim file are both loading. Use one or the other, never both.</p><h2 id="approval-prompts-hang-or-never-resolve" tabindex="-1">Approval prompts hang or never resolve <a class="header-anchor" href="#approval-prompts-hang-or-never-resolve" aria-label="Permalink to &quot;Approval prompts hang or never resolve&quot;">​</a></h2><p>OpenCode core currently drops provider-emitted approval requests instead of showing them, so the bridge resolves approvals conversationally: answer the lettered list with one option. Anything unrecognized is asked once more, then denied on timeout. A pending approval always resolves before the turn continues — nothing waits silently forever.</p><h2 id="opencode-tool-backend-is-not-verified-on-the-serving-muse-cli" tabindex="-1">&quot;opencode tool backend is not verified on the serving Muse CLI&quot; <a class="header-anchor" href="#opencode-tool-backend-is-not-verified-on-the-serving-muse-cli" aria-label="Permalink to &quot;&quot;opencode tool backend is not verified on the serving Muse CLI&quot;&quot;">​</a></h2><p>You opted into <code>OPENCODE_MUSE_TOOL_BACKEND=opencode</code> on a CLI without a passing backend probe (currently anything newer than 1.4.14, including 1.4.20). Either unset the variable for the default muse backend, or hold Muse CLI 1.4.14. See the tracking issue named in the message.</p><h2 id="muse-turn-failed-configerror" tabindex="-1">&quot;Muse turn failed (configError)&quot; <a class="header-anchor" href="#muse-turn-failed-configerror" aria-label="Permalink to &quot;&quot;Muse turn failed (configError)&quot;&quot;">​</a></h2><p>On current versions the backend gate above fires first with a clearer message. If you see a bare <code>configError</code> on a verified CLI, report it with your Muse/OpenCode/plugin versions — it means a new incompatibility, not a misconfiguration.</p><h2 id="startup-fingerprint-warning" tabindex="-1">Startup fingerprint warning <a class="header-anchor" href="#startup-fingerprint-warning" aria-label="Permalink to &quot;Startup fingerprint warning&quot;">​</a></h2><p><code>fingerprintWarning</code> lines at host start are informational: the serving CLI is newer than the SDK pin and additive drift was classified. Core chat does not depend on it. Only missing/malformed fingerprints fail closed.</p><h2 id="a-turn-was-denied-failed-closed" tabindex="-1">A turn was denied / failed closed <a class="header-anchor" href="#a-turn-was-denied-failed-closed" aria-label="Permalink to &quot;A turn was denied / failed closed&quot;">​</a></h2><p>Fail-closed is the design, not a bug: unrepresentable choices, unknown variants, unmappable rewinds, and ambiguous verdicts all stop with an explanation rather than guessing. The message always says what to do instead — usually re-prompt, start a fresh session, or adjust one variable.</p><p>Still stuck? Open an issue with versions (<code>muse --version</code>, <code>opencode --version</code>, plugin version), the exact error text, and which backend and approval mode you run. Never paste credentials, prompts, or generated text.</p>',16)])])}const g=o(r,[["render",i]]);export{c as __pageData,g as default};
